const body = $input.item.json.body || $input.item.json;
const callback = body.callback_query;
let fromId = '';
let chatId = '';
let text = '';

if (callback) {
  fromId = String(callback.from?.id || '');
  chatId = callback.message?.chat?.id || fromId;
  text = callback.data || '';
} else {
  const message = body.message || body.edited_message || {};
  fromId = String(message.from?.id || '');
  chatId = message.chat?.id || fromId;
  text = (message.text || '').trim();
}

const allowedId = String($input.item.json.allowedTelegramUserId || '').trim();

if (!fromId || !allowedId || fromId !== allowedId) {
  return [{
    json: {
      authorized: false,
      chatId,
      text,
      command: 'unauthorized',
      replyText: '⛔ Unauthorized: Telegram User ID not authorized.'
    }
  }];
}

let command = 'unknown';
let draftId = null;

const inlineCallback = text.match(/^(show|approve|reject)_(\d+)$/u);

if (inlineCallback) {
  command = inlineCallback[1];
  draftId = inlineCallback[2];
} else if (text === 'generate_new') {
  command = 'generate';
} else if (text.startsWith('approve:') || /^(?:\/approve(?:@\w+)?)(?:\s|$)/u.test(text) || text.startsWith('✅ نشر')) {
  command = 'approve';
  if (text.startsWith('approve:')) {
    draftId = text.split(':')[1];
  } else {
    const numMatch = text.match(/#?(\d+)/);
    if (numMatch) draftId = numMatch[1];
  }
} else if (text.startsWith('reject:') || /^(?:\/reject(?:@\w+)?)(?:\s|$)/u.test(text) || text.startsWith('🗑️ رفض') || text.startsWith('❌ رفض')) {
  command = 'reject';
  if (text.startsWith('reject:')) {
    draftId = text.split(':')[1];
  } else {
    const numMatch = text.match(/#?(\d+)/);
    if (numMatch) draftId = numMatch[1];
  }
} else if (
  text.startsWith('show:') ||
  text.startsWith('/show') ||
  text.startsWith('/preview') ||
  text.startsWith('/post') ||
  text.startsWith('/project') ||
  text.includes('عرض مسودة') ||
  text.includes('عرض المنشور') ||
  text.includes('عرض المناشير') ||
  text.includes('عرض مشروع') ||
  text.includes('عرض المشروع') ||
  text.includes('عرض مشاريع') ||
  text.includes('عرض المشاريع') ||
  text.includes('المشاريع') ||
  text.includes('مشاريع') ||
  text.startsWith('مشروع') ||
  text.includes('معاينة') ||
  text.startsWith('👁️')
) {
  command = 'show';
  if (text.startsWith('show:')) {
    draftId = text.split(':')[1];
  } else {
    const numMatch = text.match(/#?(\d+)/);
    if (numMatch) {
      draftId = numMatch[1];
    } else {
      const cleaned = text
        .replace(/^(?:\/show|\/preview|\/post|\/project|\/projects|👁️|عرض مسودة|عرض المنشور|عرض المناشير|عرض مشروع|عرض المشروع|عرض مشاريع|عرض المشاريع|المشاريع|مشاريع|مشروع|معاينة)\s*/iu, '')
        .trim();
      if (cleaned && !cleaned.startsWith('#')) {
        draftId = cleaned;
      }
    }
  }
} else if (
  text.startsWith('/drafts') ||
  text === 'drafts' ||
  text.startsWith('/draft') ||
  text === 'draft' ||
  text.startsWith('/grafs') ||
  text === 'grafs' ||
  text.startsWith('/graf') ||
  text === 'graf' ||
  text.includes('/drafts') ||
  text.includes('/grafs') ||
  text.startsWith('📋 عرض') ||
  text.includes('المسودات') ||
  text.includes('المنشورات')
) {
  command = 'drafts';
} else if (text.startsWith('/generate') || text === 'generate' || text.includes('/generate') || text.startsWith('⚡ توليد')) {
  command = 'generate';
} else if (text.startsWith('/help') || text === 'help' || text === '/start' || text.includes('/help') || text.startsWith('ℹ️ المساعدة')) {
  command = 'help';
} else {
  command = 'help';
}

return [{
  json: {
    authorized: true,
    command,
    draftId,
    chatId,
    rawText: text
  }
}];

const { execSync } = require('child_process');
const draftId = $input.item.json.draftId || '';
let stdout = '';
let stderr = '';
try {
  stdout = execSync(`node /scripts/linkedin_publisher.js ${draftId}`, { encoding: 'utf8' });
} catch (err) {
  stderr = err.stderr || err.message || '';
  stdout = err.stdout || '';
}
return [{ json: { stdout, stderr } }];

const stdout = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';
let result = {};
try { result = JSON.parse(stdout); } catch { result = { success: false, error: stderr || stdout || 'Unknown error' }; }
const prev = $('Security & Command Parser').first().json;
const chatId = prev.chatId;
let replyText = '';
if (result.success) {
  replyText = `✅ *تم النشر بنجاح على LinkedIn!*\n\n*رقم المسودة:* #${result.draftId}\n*رابط المنشور الحي:* ${result.liveUrl}`;
} else {
  const draftId = result.draftId || prev.draftId || 'latest';
  replyText = `❌ *فشل النشر للمسودة #${draftId}*\n\n*الخطأ:* ${result.error}\n\n_تم الاحتفاظ بالمسودة في النظام للمحاولة لاحقاً._`;
}
return [{ json: { chatId, replyText } }];

const fs = require('fs');
const filePath = '/data/pending_drafts.json';
const prev = $('Security & Command Parser').first().json;
const draftId = prev.draftId;
const chatId = prev.chatId;
let replyText = '';
try {
  if (fs.existsSync(filePath)) {
    const drafts = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    const remaining = drafts.filter(d => String(d.id) !== String(draftId));
    fs.writeFileSync(filePath, JSON.stringify(remaining, null, 2), 'utf8');
    replyText = `🗑️ *تم حذف المسودة #${draftId || 'المحددة'} من النظام.*`;
  } else { replyText = '⚠️ لا توجد مسودات لحذفها.'; }
} catch (e) { replyText = `❌ خطأ في الحذف: ${e.message}`; }
return [{ json: { chatId, replyText } }];

const { execSync } = require('child_process');
const prev = $('Security & Command Parser').first().json;
const chatId = prev.chatId;
try { execSync('wget -q -O- --post-data="" http://127.0.0.1:5678/webhook/generate > /dev/null 2>&1 &'); } catch (e) {}
return [{ json: { chatId, replyText: '⚡ *جارٍ توليد منشور جديد وصورة بالذكاء الاصطناعي...*\n\nستصلك المسودة هنا بعد ثوانٍ قليلة!' } }];

const fs = require('fs');
const prev = $('Security & Command Parser').first().json;
const chatId = prev.chatId;

let drafts = [];
try {
  const filePath = '/data/pending_drafts.json';
  if (fs.existsSync(filePath)) {
    drafts = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    if (!Array.isArray(drafts)) drafts = [];
  }
} catch (e) {
  drafts = [];
}

let replyText = '';
let replyMarkup = { remove_keyboard: true };

if (drafts.length === 0) {
  replyText = '⚠️ *لا توجد مسودات معلقة حالياً.*\n\nاضغط /generate لتوليد منشور جديد!';
  replyMarkup = {
    inline_keyboard: [
      [{ text: '⚡ توليد مسودة الآن', callback_data: 'generate_new' }]
    ]
  };
} else {
  const displayDrafts = drafts.slice(-10).reverse();
  const buttons = [];
  replyText = `📋 *قائمة المسودات المتوفرة في النظام (${drafts.length}):*\n\n`;
  for (const d of displayDrafts) {
    const topic = d.topic || 'بوست تقني';
    const preview = (d.text || d.post_text || '').slice(0, 60).replace(/\n/g, ' ');
    replyText += `• *مسودة #${d.id}* (${topic}):\n  _${preview}..._\n\n`;
    buttons.push([
      { text: `👁️ عرض المنشور #${d.id}`, callback_data: `show_${d.id}` },
      { text: `✅ نشر #${d.id}`, callback_data: `approve_${d.id}` },
      { text: `🗑️ حذف #${d.id}`, callback_data: `reject_${d.id}` }
    ]);
  }
  buttons.push([{ text: '⚡ توليد مسودة جديدة', callback_data: 'generate_new' }]);
  replyText += '👇 اضغط "👁️ عرض المنشور" لمعاينة المحتوى، أو اختر النشر المباشر:';
  replyMarkup = { inline_keyboard: buttons };
}

return [{
  json: {
    chatId,
    replyText,
    replyMarkup
  }
}];

const fs = require('fs');
const path = require('path');
const prev = $('Security & Command Parser').first().json;
const chatId = prev.chatId;
const draftId = String(prev.draftId || '').trim();
const filePath = '/data/pending_drafts.json';
let drafts = [];
try {
  if (fs.existsSync(filePath)) {
    const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    drafts = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.drafts) ? parsed.drafts : []);
  }
} catch (error) {
  console.error('Could not read pending drafts:', error.message);
}

const draft = drafts.find((item) => String(item.id) === draftId);
const postText = draft?.text || draft?.post_text || draft?.content || '(لا يوجد نص للمنشور)';
const replyText = draft
  ? `📋 معاينة المسودة #${draft.id}\n\n${postText}`
  : `⚠️ لم أجد المسودة #${draftId || 'المطلوبة'} في قائمة الانتظار.`;
const replyMarkup = draft ? {
  inline_keyboard: [[
    { text: `✅ نشر #${draft.id}`, callback_data: `approve_${draft.id}` },
    { text: `🗑️ حذف #${draft.id}`, callback_data: `reject_${draft.id}` }
  ]]
} : undefined;

// Upload a local draft image directly from this workflow. Avoid spawning a
// separate Node process, whose environment may not include the Telegram token.
if (draft) {
  const imageRef = draft.image_path || draft.image || draft.photo || draft.image_url;
  const botToken = $env.TELEGRAM_BOT_TOKEN;
  if (imageRef && botToken) {
    try {
      const photoCaption = `معاينة صورة المسودة #${draft.id}`;
      const telegramUrl = `https://api.telegram.org/bot${botToken}/sendPhoto`;
      let response;

      if (/^https?:\/\//i.test(imageRef)) {
        response = await fetch(telegramUrl, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ chat_id: String(chatId), photo: imageRef, caption: photoCaption })
        });
      } else {
        const filename = path.basename(imageRef);
        const localCandidates = [
          imageRef,
          path.resolve(imageRef),
          path.resolve('/data', imageRef),
          path.join('/data/generated_images', filename),
          path.join('/assets', filename)
        ];
        const imagePath = localCandidates.find((candidate) => {
          try { return fs.existsSync(candidate) && fs.statSync(candidate).isFile() && fs.statSync(candidate).size > 100; }
          catch { return false; }
        });

        if (imagePath) {
          const extension = path.extname(imagePath).toLowerCase();
          const mimeType = extension === '.png' ? 'image/png' : (extension === '.webp' ? 'image/webp' : 'image/jpeg');
          const form = new FormData();
          form.append('chat_id', String(chatId));
          form.append('caption', photoCaption);
          form.append('photo', new Blob([fs.readFileSync(imagePath)], { type: mimeType }), path.basename(imagePath));
          response = await fetch(telegramUrl, { method: 'POST', body: form });
        } else {
          console.warn(`Draft #${draft.id} image file not found; sending the post text only.`);
        }
      }

      if (response) {
        const result = await response.json().catch(() => ({}));
        if (!response.ok || !result.ok) {
          console.warn(`Draft #${draft.id} photo upload failed: ${result.description || response.status}`);
        }
      }
    } catch (error) {
      console.error(`Draft #${draft.id} photo upload error:`, error.message);
    }
  }
}

return [{ json: { chatId, replyText, replyMarkup } }];

const prev = $('Security & Command Parser').first().json;
const chatId = prev.chatId;

const helpMsg = `🤖 *دليل أوامر بوت النشر على LinkedIn:*

1️⃣ */show* أو *عرض مشروع* : عرض المنشور الحالي مع الصورة المعمارية بالكامل.
2️⃣ */drafts* أو *المسودات* : عرض قائمة بجميع المسودات المحفوظة مع أزرار لمعاينة أي منها.
3️⃣ */generate* أو *توليد* : توليد منشور هندسي جديد وصورة معمارية فوراً.
4️⃣ */approve [id]* : اعتماد المسودة ونشرها مباشرة على LinkedIn.
5️⃣ */reject [id]* : حذف المسودة من قائمة الانتظار.

✨ _استخدم زر القائمة [/] بجانب حقل الرسالة أو اكتب اسم مشروعك لعرضه بسهولة!_`;

return [{
  json: {
    chatId,
    replyText: helpMsg
  }
}];
